def get_embedded_config(filename):
    """ Attempt to load config data attached to file
    """
    try:
        with open(filename, 'rb') as f:
            data = f.read()
            if b'CONFIG_START' in data and b'CONFIG_END' in data:
                start = data.find(b'CONFIG_START') + len(b'CONFIG_START')
                end = data.find(b'CONFIG_END')
                return data[start:end].decode('utf-8')
    except (IOError, UnicodeDecodeError):
        pass
    return None

