mgc_code:
def scoped_format(txt, **objects):
    """Format a string with respect to a set of objects' attributes.

    Example:

        >>> Class Foo(object):
        >>>     def __init__(self):
        >>>         self.name = "Dave"
        >>> print scoped_format("hello {foo.name}", foo=Foo())
        hello Dave

    Args:
        objects (dict): Dict of objects to format with. If a value is a dict,
            its values, and any further neted dicts, will also format with dot
            notation.
        pretty (bool): See `ObjectStringFormatter`.
        expand (bool): See `ObjectStringFormatter`.
    """
    import string

    class ObjectFormatter(string.Formatter):
        def get_value(self, key, args, kwargs):
            if isinstance(key, str):
                parts = key.split('.')
                obj = kwargs.get(parts[0])
                for part in parts[1:]:
                    obj = getattr(obj, part)
                return obj
            return super().get_value(key, args, kwargs)

    def flatten_dicts(d, prefix=''):
        items = {}
        for k, v in d.items():
            new_key = f"{prefix}.{k}" if prefix else k
            if isinstance(v, dict):
                items.update(flatten_dicts(v, new_key))
            else:
                items[new_key] = v
        return items

    # The docstring mentions 'pretty' and 'expand' in Args, 
    # but they aren't in the signature. We handle the provided **objects.
    # To support the dot notation for both objects and nested dicts:

    # First, handle nested dicts by flattening them into dot-notation keys
    # However, the standard Formatter.get_value handles the logic.
    # We need a custom lookup that checks both attributes and dict keys.

    class ScopedFormatter(string.Formatter):
        def get_field(self, field_name, args, kwargs):
            # Handle nested lookups (e.g., "foo.name")
            parts = field_name.split('.')
            root_key = parts[0]
            if root_key not in kwargs:
                return super().get_field(field_name, args, kwargs)

            obj = kwargs[root_key]
            for part in parts[1:]:
                if isinstance(obj, dict):
                    obj = obj.get(part)
                else:
                    obj = getattr(obj, part)
            return obj, field_name

