def waitForResponse(self, timeOut=None):
        """blocks until the response arrived or timeout is reached."""
        import time
        start_time = time.time()
        while not self.has_response():
            if timeOut is not None and (time.time() - start_time) >= timeOut:
                return False
            time.sleep(0.01)
        return True

