def process_udp_frame(self,
                          id=None,
                          msg=None):
        """process_udp_frame

        Convert a complex nested json dictionary
        to a flattened dictionary and capture
        all unique keys for table construction

        :param id: key for this msg
        :param msg: udp frame for packet
        """
        if msg is None:
            return

        flattened = {}
        def flatten(current_data, prefix=''):
            if isinstance(current_data, dict):
                for key, value in current_data.items():
                    new_key = f"{prefix}_{key}" if prefix else key
                    flatten(value, new_key)
            elif isinstance(current_data, list):
                for i, value in enumerate(current_data):
                    new_key = f"{prefix}_{i}"
                    flatten(value, new_key)
            else:
                flattened[prefix] = current_data

        flatten(msg)
        if id is not None:
            flattened['id'] = id

        if not hasattr(self, 'all_keys'):
            self.all_keys = set()

        self.all_keys.update(flattened.keys())
        return flattened

