mgc_code:
def psql_to_obj(cls, file_path=None, text='', columns=None,
                    remove_empty_rows=True, key_on=None,
                    deliminator=' | ', eval_cells=True):
        """
        This will convert a psql file or text to a seaborn table
        :param file_path: str of the path to the file
        :param text: str of the csv text
        :param columns: list of str of columns to use
        :param remove_empty_rows: bool if True will remove empty rows
        :param key_on: list of str of columns to key on
        :param deliminator: str to use as a deliminator
        :param eval_cells: bool if True will try to evaluate numbers
        :return: SeabornTable
        """
        import pandas as pd
        import ast

        if file_path:
            with open(file_path, 'r') as f:
                content = f.read()
        else:
            content = text

        lines = [line.strip() for line in content.splitlines() if line.strip()]

        # Remove psql decorative borders (lines consisting of - or |)
        data_lines = []
        for line in lines:
            if line.startswith('-') and line.endswith('-'):
                continue
            data_lines.append(line)

        rows = []
        for line in data_lines:
            # Strip leading/trailing delimiters
            stripped = line.strip(deliminator.strip())
            row = [cell.strip() for cell in stripped.split(deliminator)]
            rows.append(row)

        if not rows:
            return cls()

        if columns:
            df = pd.DataFrame(rows, columns=columns)
        else:
            df = pd.DataFrame(rows[1:], columns=rows[0])

        if remove_empty_rows:
            df = df.dropna(how='all').replace('', pd.NA).dropna(how='all')

        if eval_cells:
            def try_eval(val):
                if pd.isna(val) or val == '':
                    return val
                try:
                    return ast.literal_eval(val)
                except (ValueError, SyntaxError):
                    return val
            df = df.applymap(try_eval)

        if key_on:
            df = df.set_index(key_on)

        return cls(df)

