def getQueueStats(self):
        """Query Asterisk Manager Interface for Queue Stats.

        CLI Command: queue show

        @return: Dictionary of queue stats.

        """
        action = 'QueueStatus'
        response = self.send_action(action)
        stats = {}

        if response and 'QueueName' in response:
            # Handle single queue response
            stats[response['QueueName']] = response
        elif response and isinstance(response, list):
            # Handle multiple queue responses
            for item in response:
                if 'QueueName' in item:
                    stats[item['QueueName']] = item

        return stats

