        """
        mapping = {
            'S': Flag.SEEN,
            'D': Flag.DRAFT,
            'F': Flag.FLAGGED,
            'R': Flag.ANSWERED,
        }
        return frozenset(mapping[c] for c in codes if c in mapping)

