            sys.stdout.write(line)
            continue
        parts = line.strip().split('\t')
        if len(parts) < 9:
            sys.stdout.write(line)
            continue
        attr_str = parts[8]
        attrs = attr_str.split(';')
        new_attrs = []
        for attr in attrs:
            if not attr: continue
            kv = attr.split('=', 1)
            if len(kv) == 2 and kv[0] == 'ID' and kv[1] in id_map:
                new_attrs.append(f"ID={id_map[kv[1]]}")
            else:
                new_attrs.append(attr)
        parts[8] = ';'.join(new_attrs)
        sys.stdout.write('\t'.join(parts) + '\n')

