if chunks is None:

    if hasattr(data, 'chunklen') and hasattr(data, 'shape'):
        # bcolz carray, chunk first dimension only
        return (data.chunklen,) + data.shape[1:]

    elif hasattr(data, 'chunks') and hasattr(data, 'shape') and \
            len(data.chunks) == len(data.shape):
        # h5py dataset or zarr array
        return data.chunks

    else:
        # fall back to something simple, ~4Mb chunks of first dimension
        row = np.asarray(data[0])
        chunklen = max(1, (2**22) // row.nbytes)
        if row.shape:
            chunks = (chunklen,) + row.shape
        else:
            chunks = (chunklen,)
        return chunks

else:

    return chunks

raw_output:
if chunks is None:
    import numpy as np
    data = np.asanyarray(data)
    shape = data.shape
    if not shape:
        return (1,)

    # Target a total chunk size of roughly 1MB (assuming float64)
    target_size = 1024 * 1024 // 8
    total_elements = np.prod(shape)

    if total_elements <= target_size:
        return shape

    scale = (target_size / total_elements) ** (1.0 / len(shape))
    return tuple(max(1, int(s * scale)) for s in shape)

return chunks

