        import numpy as np
        data = np.asanyarray(data)
        shape = data.shape
        if not shape:
            return (1,)

        # Target a total chunk size of roughly 1MB (assuming float64)
        target_size = 1024 * 1024 // 8
        total_elements = np.prod(shape)

        if total_elements <= target_size:
            return shape

        scale = (target_size / total_elements) ** (1.0 / len(shape))
        return tuple(max(1, int(s * scale)) for s in shape)

    return chunks

