def say_bitly_short_url(self, message, long_url=None):
        """bitly ___: Shorten long_url using bitly service."""
        if not long_url:
            return message

        import requests

        # This assumes the class has a bitly_token attribute
        api_url = "https://api-ssl.bitly.com/v4/shorten"
        headers = {
            "Authorization": f"Bearer {self.bitly_token}",
            "Content-Type": "application/json"
        }
        payload = {"long_url": long_url}

        try:
            response = requests.post(api_url, json=payload, headers=headers)
            response.raise_for_status()
            short_url = response.json().get("link")
            return f"{message} {short_url}"
        except Exception:
            return f"{message} {long_url}"

