        """ Moodustame lausealguliste pärisnimede loendi: vaatame sõnu, millel nii
            pärisnimeanalüüs(id) kui ka mittepärisnimeanalüüs(id) ning mis esinevad 
            lause või nummerdatud loendi alguses - jäädvustame selliste sõnade 
            unikaalsed lemmad;
        """
        initial_proper_names = set()
        for doc in docs:
            for sentence in doc.sentences:
                if not sentence.tokens:
                    continue

                first_token = sentence.tokens[0]
                # Check if the token has both proper name and non-proper name analyses
                has_proper = any(a.is_proper_name for a in first_token.analyses)
                has_non_proper = any(not a.is_proper_name for a in first_token.analyses)

                if has_proper and has_non_proper:
                    initial_proper_names.add(first_token.lemma)

        return list(initial_proper_names)

