def guess_payload_class(self, payload):
        """DEV: Guesses the next payload class from layer bonds. Can be overloaded to use a different mechanism."""
        if not payload:
            return None

        # Check for common payload markers or layer bond attributes
        # This is a generic implementation that can be overridden
        if hasattr(payload, 'payload_class'):
            return payload.payload_class

        if hasattr(payload, 'layer_bonds'):
            bonds = payload.layer_bonds
            if bonds and len(bonds) > 0:
                # Return the class associated with the first bond
                return bonds[0].get('class')

        return None

