def decrypt_attributes(self, attribute_statement):
        """
        Decrypts possible encrypted attributes and adds the decrypts to the
        list of attributes.

        :param attribute_statement: A SAML.AttributeStatement which might
            contain both encrypted attributes and attributes.
        """
        if attribute_statement.encrypted_attributes:
            for encrypted_attr in attribute_statement.encrypted_attributes:
                decrypted_attr = self.decrypt_attribute(encrypted_attr)
                if decrypted_attr:
                    attribute_statement.attributes.append(decrypted_attr)

