def dump_dict(cfg, f, indent=0):
    """Save a dictionary of attributes"""
    spacing = ' ' * indent
    for k, v in cfg.items():
        if isinstance(v, dict):
            f.write(f"{spacing}{k}:\n")
            dump_dict(v, f, indent + 4)
        else:
            f.write(f"{spacing}{k}: {v}\n")

