mgc_code:
def GetResources(filename, types=None, names=None, languages=None):
    """
    Get resources from dll/exe file.

    types = a list of resource types to search for (None = all)
    names = a list of resource names to search for (None = all)
    languages = a list of resource languages to search for (None = all)
    Return a dict of the form {type_: {name: {language: data}}} which 
    might also be empty if no matching resources were found.

    """
    import pefile

    pe = pefile.PE(filename)
    resources = {}

    if not hasattr(pe, 'DIRECTORY_ENTRY_RESOURCE'):
        return resources

    for resource_type in pe.DIRECTORY_ENTRY_RESOURCE.entries:
        type_id = resource_type.id
        if types is not None and type_id not in types:
            continue

        type_dict = {}
        for resource_name in resource_type.directory:
            name_id = resource_name.id
            if names is not None and name_id not in names:
                continue

            name_dict = {}
            for resource_lang in resource_name.directory:
                lang_id = resource_lang.id
                if languages is not None and lang_id not in languages:
                    continue

                data_rva = resource_lang.data.struct.OffsetToData
                size = resource_lang.data.struct.Size
                data = pe.get_data(data_rva, size)
                name_dict[lang_id] = data

            if name_dict:
                type_dict[name_id] = name_dict

        if type_dict:
            resources[type_id] = type_dict

    return resources

