    match = psm if psm is not None else 2
    mismatch = pmm if pmm is not None else -0.5
    gap_open = pgo if pgo is not None else -3
    gap_extend = pge if pge is not None else -1

    if matrix is None:
        alignments = pairwise2.align.localms(s1, s2, match, mismatch, gap_open, gap_extend)
    else:
        alignments = pairwise2.align.localdx(s1, s2, matrix, gap_open, gap_extend)
else:
    if matrix is not None:
        alignments = pairwise2.align.localdx(s1, s2, matrix, pgo or -10, pge or -0.5)
    else:
        alignments = pairwise2.align.localms(s1, s2, psm or 2, pmm or -1, pgo or -10, pge or -0.5)

