mgc_code:
def parse(query_string, unquote=True, normalized=False, encoding=DEFAULT_ENCODING):
    """
    Main parse function
    @param query_string:
    @param unquote: unquote html query string ?
    @param encoding: An optional encoding used to decode the keys and values. Defaults to utf-8, which the W3C declares as a defaul in the W3C algorithm for encoding.
    @see http://www.w3.org/TR/html5/forms.html#application/x-www-form-urlencoded-encoding-algorithm

    @param normalized: parse number key in dict to proper list ?
    """
    import urllib.parse

    if not query_string:
        return {}

    params = urllib.parse.parse_qs(query_string, keep_blank_values=True, encoding=encoding)

    if not unquote:
        # parse_qs automatically unquotes; we must re-quote if unquote=False
        # However, standard parse_qs doesn't provide a "don't unquote" flag.
        # To strictly follow the request, we manually handle the string if unquote is False.
        params = {}
        for pair in query_string.split('&'):
            if not pair: continue
            if '=' in pair:
                k, v = pair.split('=', 1)
            else:
                k, v = pair, ''
            params.setdefault(k, []).append(v)

    if normalized:
        result = {}
        for k, v in params.items():
            # Attempt to convert numeric strings to actual numbers
            processed_vals = []
            for item in v:
                try:
                    if '.' in item:
                        processed_vals.append(float(item))
                    else:
                        processed_vals.append(int(item))
                except ValueError:
                    processed_vals.append(item)
            result[k] = processed_vals
        return result

    return params

