def passthrough_repl(self, inputstring, **kwargs):
        """Add back passthroughs."""
        import re
        pattern = r'\{\{(.*?)\}\}'
        def replace(match):
            key = match.group(1)
            return str(kwargs.get(key, match.group(0)))
        return re.sub(pattern, replace, inputstring)

