def _merge_dicts_(a, b):
    for key in set(a.keys()).union(b.keys()):
        if key in a and key in b:
            if isinstance(a[key], dict) and isinstance(b[key], dict):
                yield (key, dict(_merge_dicts_(a[key], b[key])))
            elif b[key] is not None:
                yield (key, b[key])
            else:
                yield (key, a[key])
