def _next(self):
        """get the next character, excluding comments. peek() is used to see
           if a '/' is followed by a '/' or '*'.
        """
        char = self.get_char()
        while char:
            if char == '/':
                next_char = self.peek()
                if next_char == '/':
                    while char and char != '\n':
                        char = self.get_char()
                    if char == '\n':
                        char = self.get_char()
                    continue
                elif next_char == '*':
                    self.get_char()  # consume '*'
                    while char and not (char == '*' and self.peek() == '/'):
                        char = self.get_char()
                    if char:
                        self.get_char()  # consume '/'
                    char = self.get_char()
                    continue
            return char
        return None

