def jinja_node_to_python(node):
    """Converts a Jinja2 node to its python equivalent
    """
    if isinstance(node, nodes.Const):
        return node.value
    if isinstance(node, nodes.Neg):
        return -jinja_node_to_python(node.node)
    if isinstance(node, nodes.Name):
        return node.name
    if isinstance(node, (nodes.List, nodes.Tuple)):
        value = []
        for i in node.items:
            value.append(jinja_node_to_python(i))
        return value
    if isinstance(node, nodes.Dict):
        value = {}
        for pair in node.items:
            value[pair.key.value] = jinja_node_to_python(pair.value)
        return value
    if isinstance(node, nodes.Call):
        if not isinstance(node.node, nodes.Name) or node.node.name not in ("_", "translate", "gettext"):
            raise FormDefinitionError("Cannot convert function calls from jinja to python other than translation calls")
        return lazy_translate(jinja_node_to_python(node.args[0]))
    raise Exception("Cannot convert jinja nodes to python")

mgc_code:
def jinja_node_to_python(node):
    """Converts a Jinja2 node to its python equivalent
    """
    if node is None:
        return None

    from jinja2.nodes import Name, Constant, GetAttr, GetItem, Call, BinOp, UnaryOp, Load

    if isinstance(node, Name):
        return node.name
    elif isinstance(node, Constant):
        return repr(node.value)
    elif isinstance(node, GetAttr):
        return f"{jinja_node_to_python(node.node)}.{node.attr}"
    elif isinstance(node, GetItem):
        return f"{jinja_node_to_python(node.node)}[{jinja_node_to_python(node.arg)}]"
    elif isinstance(node, Call):
        args = ", ".join(jinja_node_to_python(arg) for arg in node.args)
        kwargs = ", ".join(f"{k}={jinja_node_to_python(v)}" for k, v in node.kwargs)
        all_args = ", ".join(filter(None, [args, kwargs]))
        return f"{jinja_node_to_python(node.node)}({all_args})"
    elif isinstance(node, BinOp):
        ops = {'+': '+', '-': '-', '*': '*', '/': '/', '//': '//', '%': '%', '**': '**', 
               '==': '==', '!=': '!=', '<': '<', '>': '>', '<=': '<=', '>=': '>=', 
               'and': 'and', 'or': 'or', '|': '|', '&': '&', '^': '^'}
        return f"{jinja_node_to_python(node.left)} {ops.get(node.operator, node.operator)} {jinja_node_to_python(node.right)}"
    elif isinstance(node, UnaryOp):
        return f"{node.operator} {jinja_node_to_python(node.node)}"
    elif isinstance(node, Load):
        return jinja_node_to_python(node.node)

    return str(node)

