def group_by_key_impl(sequence):
    """
    Implementation for group_by_key_t
    :param sequence: sequence to group
    :return: grouped sequence
    """
    result = {}
    for item in sequence:
        key = item[0]
        if key not in result:
            result[key] = []
        result[key].append(item)
    return result

